  useEffect(() => {
    // Auto-focus the textarea when it appears
    setTimeout(() => inputRef.current?.focus(), 50);
  }, []);

  const handleSubmit = () => {
    if (!notes.trim()) return;
    onSubmit({
      taskId,
      taskName,
      type: 'down',
      notes,
      images: [],
      timestamp: Date.now(),
      mode: 'text',
      taskDescription,
    });
