          <span className="text-xs text-white/80 font-medium truncate">{task.title || task.taskId}</span>
          <span className={`text-[10px] ${statusColor[task.status] || 'text-white/40'} truncate`}>
            {statusLabel[task.status] || task.status}
          </span>
        </div>

        {/* Inline approval indicator for approved/rejected */}
        {isApproved && (
          <div className="flex items-center justify-center w-7 h-7 rounded-lg text-green-400/80 bg-green-400/10 flex-shrink-0">
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
            </svg>
          </div>
        )}
        {isRejected && (
