export function ActiveJobsWidget() {
  const { jobs, completedHistory, dismissJob } = useActiveJobs();
  const { effectiveIsMobile } = useLayoutMode();
  const { wonderChromeMode } = useUI();
  const [wonderSceneId, setWonderSceneId] = useState<string | null>(null);
  const [polledTasks, setPolledTasks] = useState<PolledTask[]>([]);
  /** Local approval overrides — applied immediately while waiting for server to confirm */
  const [localApprovals, setLocalApprovals] = useState<Map<string, string>>(new Map());

  // Poll /api/tasks every 5 seconds
  useEffect(() => {
    let cancelled = false;

    const fetchTasks = async () => {
      try {
        const res = await fetch('/api/tasks');
        if (res.ok) {
          const data = await res.json();
          if (!cancelled && Array.isArray(data.tasks)) {
            setPolledTasks(data.tasks);
          }
        }
      } catch {
        // silently ignore fetch errors
      }
    };

    fetchTasks();
    const interval = setInterval(fetchTasks, 5000);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, []);

  /** Handle approval/rejection from PolledTaskCard — optimistic local update */
  const handlePolledApproval = useCallback((taskId: string, action: 'approve' | 'reject') => {
    setLocalApprovals((prev) => {
      const next = new Map(prev);
      next.set(taskId, action === 'approve' ? 'approved' : 'rejected');
      return next;
    });
  }, []);

  /** Filter out approved/rejected tasks, sort the rest */
  const sortedPolledTasks = [...polledTasks]
    .filter((t) => {
      // Hide tasks that have been approved or rejected
      const localStatus = localApprovals.get(t.taskId);
      const effectiveStatus = localStatus || t.approvalStatus;
      return effectiveStatus !== 'approved' && effectiveStatus !== 'rejected' && effectiveStatus !== 'rework';
    })
    .map((t) => {
      const localStatus = localApprovals.get(t.taskId);
      if (localStatus && !t.approvalStatus) {
        return { ...t, approvalStatus: localStatus };
      }
      return t;
    })
    .sort((a, b) => {
    const order: Record<string, number> = { running: 0, pending: 1, failed: 2, complete: 3 };
    const aOrder = order[a.status] ?? 99;
    const bOrder = order[b.status] ?? 99;
    if (aOrder !== bOrder) return aOrder - bOrder;
    // Within complete: unapproved first, then rejected, then approved last
    if (a.status === 'complete' && b.status === 'complete') {
      const approvalOrder = (s?: string) => {
        if (!s || s === 'pending') return 0;
        if (s === 'rejected' || s === 'rework') return 1;
        if (s === 'approved') return 2;
        return 0;
      };
      return approvalOrder(a.approvalStatus) - approvalOrder(b.approvalStatus);
    }
    return 0;
  });

  const wonderJobsHidden = wonderChromeMode === 'full';

  useEffect(() => {
    const handleWonderScene = (e: Event) => {
      const payload = (e as CustomEvent).detail?.payload ?? {};
      if (payload.sceneId) {
        setWonderSceneId(String(payload.sceneId));
      }
    };
    const handleWonderClear = () => {
      setWonderSceneId(null);
    };
    window.addEventListener('nia:wonder.scene', handleWonderScene);
    window.addEventListener('nia:wonder.clear', handleWonderClear);
    return () => {
      window.removeEventListener('nia:wonder.scene', handleWonderScene);
      window.removeEventListener('nia:wonder.clear', handleWonderClear);
    };
  }, []);

  const isMobile = effectiveIsMobile;
  const [mobileExpanded, setMobileExpanded] = useState(false);
  const [desktopExpanded, setDesktopExpanded] = useState(false);
  const { currentMode } = useDesktopMode();
  const {
    feedbackState,
    inlineFeedbackTaskId,
    submitting,
    handleThumbsUp: rawThumbsUp,
    openInlineFeedback,
    closeInlineFeedback,
    submitFeedback: rawSubmitFeedback,
  } = useTaskFeedback();

  const handleThumbsUp = useCallback(async (taskId: string, taskName: string) => {
    await rawThumbsUp(taskId, taskName);
    dismissJob(taskId);
  }, [rawThumbsUp, dismissJob]);

  const handleThumbsDown = useCallback((taskId: string, taskName: string) => {
    openInlineFeedback(taskId, taskName);
  }, [openInlineFeedback]);

  const handleSubmitInlineFeedback = useCallback(async (feedback: { taskId: string; taskName: string; type: 'down'; notes: string; images: File[]; timestamp: number; mode: 'text'; taskDescription?: string }) => {
    await rawSubmitFeedback(feedback);
    dismissJob(feedback.taskId);
  }, [rawSubmitFeedback, dismissJob]);

  useEffect(() => {
    setMobileExpanded(false);
  }, [currentMode]);

  const containerRef = useRef<HTMLDivElement>(null);
  const desktopContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    ensureGohufont();
  }, []);

  const completedIds = new Set(completedHistory.map((j) => j.id));
  const visibleJobs = jobs.filter(
    (j) => (j.status === 'running' || j.status === 'complete' || j.status === 'failed' || j.label)
      && !completedIds.has(j.id)
  );

  const hasActiveJobs = visibleJobs.length > 0;
  const hasPolledTasks = polledTasks.length > 0;
  const hasRunning = visibleJobs.some((j) => j.status === 'running') || polledTasks.some((t) => t.status === 'running');
  const hasFailed = visibleJobs.some((j) => j.status === 'failed') || polledTasks.some((t) => t.status === 'failed');

  // Shared job list rendering
  const renderJobList = () => (
    <>
      {/* Active job cards */}
      {hasActiveJobs && visibleJobs.map((job) => (
        <JobCard
          key={job.id}
          job={job}
          feedbackGiven={feedbackState.submitted.get(job.id)}
          showInlineFeedback={inlineFeedbackTaskId === job.id}
          onThumbsUp={handleThumbsUp}
          onThumbsDown={handleThumbsDown}
          onSubmitFeedback={handleSubmitInlineFeedback}
          onCancelFeedback={closeInlineFeedback}
          submittingFeedback={submitting}
        />
      ))}

      {/* Polled tasks from /api/tasks */}
      {hasPolledTasks && (
        <>
          {hasActiveJobs && (
            <div className="text-[10px] text-white/30 px-2 py-0.5 uppercase tracking-wider" style={{ fontFamily: 'Gohufont, monospace' }}>
              ─── queued tasks ───
            </div>
          )}
          {sortedPolledTasks.map((task) => (
            <PolledTaskCard key={task.taskId} task={task} onApprovalChange={handlePolledApproval} />
          ))}
        </>
      )}

      {/* Completed jobs history */}
      {completedHistory.length > 0 && (
        <>
          {(hasActiveJobs || hasPolledTasks) && (
            <div className="text-[10px] text-white/30 px-2 py-0.5 uppercase tracking-wider" style={{ fontFamily: 'Gohufont, monospace' }}>
              ─── completed ───
            </div>
          )}
          {completedHistory.map((job) => (
            <CompletedJobCard
              key={job.id}
              job={job}
              feedbackGiven={feedbackState.submitted.get(job.id)}
              showInlineFeedback={inlineFeedbackTaskId === job.id}
              onThumbsUp={handleThumbsUp}
              onThumbsDown={handleThumbsDown}
              onSubmitFeedback={handleSubmitInlineFeedback}
              onCancelFeedback={closeInlineFeedback}
              submittingFeedback={submitting}
            />
          ))}
        </>
      )}

      {/* Empty state */}
      {!hasActiveJobs && !hasPolledTasks && completedHistory.length === 0 && (
        <div
          className="px-3 py-2 text-[11px] text-white/30 italic"
          style={{ fontFamily: 'Gohufont, monospace' }}
        >
          No activity yet. Tasks will appear here.
        </div>
      )}
    </>
  );

  const baseRightPx = 56; // Tailwind right-14
  const sceneRightShift: Record<string, number> = {
    // News has the most header controls, so shift it further left.
    news: 0,
    // Weather needs a smaller offset than news but still enough to clear its controls.
    weather: 0,
  };
  const extraRightPx = wonderSceneId ? sceneRightShift[wonderSceneId] ?? 0 : 0;
  const computedRight = baseRightPx + extraRightPx;

  // ── Desktop ─────────────────────────────
  if (!isMobile) {
    return (
      <div
        ref={desktopContainerRef}
        className={`fixed top-3 z-[450] flex flex-col items-end gap-2 transition-opacity duration-200 ${wonderJobsHidden ? 'opacity-0 pointer-events-none' : 'opacity-100'}`}
        style={{ pointerEvents: wonderJobsHidden ? 'none' : 'auto', right: `${computedRight}px` }}
      >
        {/* Pill button — ALWAYS visible */}
        <div className={desktopExpanded ? 'flex justify-end' : ''}>
          <GearToggleButton
            count={visibleJobs.length + polledTasks.length}
            hasRunning={hasRunning}
            hasFailed={hasFailed}
            expanded={desktopExpanded}
            onClick={() => setDesktopExpanded((v) => !v)}
            completedCount={completedHistory.length}
          />
        </div>

        {/* Expanded job list — flush-right with 10px padding */}
        {desktopExpanded && (
          <div
            className="fixed flex flex-col items-end gap-2"
            style={{ right: '10px', top: 'calc(0.75rem + 44px)', zIndex: 450, maxWidth: 'min(380px, calc(100vw - 20px))' }}
          >
            {renderJobList()}
          </div>
        )}
      </div>
    );
  }

  // ── Mobile ────────────────────────────
  return (
    <div
      ref={containerRef}
      className={`fixed z-[450] flex flex-col items-end gap-2 transition-opacity duration-200 ${wonderJobsHidden ? 'opacity-0' : 'opacity-100'}`}
      style={{
        pointerEvents: 'none',
        // Match top-3 with PersistentNavButtons + Wonder close (mobile close is ~12px + safe-area).
        // News used to use a larger top offset when the Wonder X sat at 56px; that is no longer needed.
        top: '0.75rem',
        right: `${computedRight}px`,
      }}
    >
      <div style={{ pointerEvents: 'auto' }}>
        <GearToggleButton
          count={visibleJobs.length + polledTasks.length}
          hasRunning={hasRunning}
          hasFailed={hasFailed}
          expanded={mobileExpanded}
          onClick={() => setMobileExpanded((v) => !v)}
          completedCount={completedHistory.length}
        />
      </div>

      <div
        className={`
          flex flex-col gap-1.5 pt-1
          transition-all duration-300 ease-out origin-top-right
          ${mobileExpanded ? 'opacity-100 scale-100' : 'opacity-0 scale-95 pointer-events-none'}
        `}
        style={{
          pointerEvents: mobileExpanded ? 'auto' : 'none',
          // Portrait mobile: anchor to screen right edge to prevent left-side cropping
          position: 'fixed',
          right: '8px',
          top: 'calc(0.75rem + 44px)',
          alignItems: 'flex-end',
          maxHeight: mobileExpanded ? 'calc(100dvh - 200px)' : '0px',
          overflowY: 'auto',
          overflowX: 'hidden',
          WebkitOverflowScrolling: 'touch',
          scrollbarWidth: 'thin',
          transition: 'opacity 0.3s ease-out, transform 0.3s ease-out, max-height 0.3s ease-out',
        }}
      >
        {renderJobList()}
      </div>
    </div>
  );
}

